import{installGroundSplit}from'./foreground-split.js';
import{cellRenderIntent,objectRenderRoleAt,gateRenderRoleAt}from'./render-intent.js';
const clone=x=>structuredClone(x),id=(m,x,y)=>m+':'+x+','+y;
function visualState(map,x,y){const i=y*map.width+x;return{movement:map.movement?.[i],tiles:Object.fromEntries(['ground','details','objects','overhead'].map(k=>[k,map.layers[k]?.[i]??null])),objects:(map.objects||[]).filter(o=>x>=o.x&&y>=o.y&&x<o.x+o.w&&y<o.y+o.h).map(o=>[o.id,objectRenderRoleAt(o,x,y),o.x,o.y,o.w,o.h]),assemblies:(map.nativeAssemblies||[]).filter(a=>x>=a.x&&y>=a.y&&x<a.x+a.w&&y<a.y+a.h).map(a=>[a.id,a.renderIntents?.[(y-a.y)*a.w+x-a.x],a.overlay?.mask?.[(y-a.y)*a.w+x-a.x]]),gates:(map.gates||[]).map(g=>[g.id,gateRenderRoleAt(g,x,y)])};}
export function auditProjectLayers(project){const out=[];for(const map of project.maps)for(let i=0;i<(map.movement?.length||0);i++){if(map.movement[i]?.mode!=='behind')continue;const x=i%map.width,y=Math.floor(i/map.width),v=cellRenderIntent(map,x,y),below=['details','objects','overhead'].some(k=>map.layers[k]?.[i]?.renderRole==='behind')||(map.objects||[]).some(o=>x>=o.x&&y>=o.y&&x<o.x+o.w&&y<o.y+o.h&&objectRenderRoleAt(o,x,y)==='behind');if(!v||v.foreground&&!below)continue;const state=JSON.stringify(visualState(map,x,y)),key=id(map.id,x,y),saved=project.layerDecisions?.[key];if(saved?.choice==='visual'&&saved.state===state)continue;const hasArtwork=['details','objects','overhead'].some(k=>map.layers[k]?.[i])||(map.objects||[]).some(o=>x>=o.x&&y>=o.y&&x<o.x+o.w&&y<o.y+o.h)||(map.nativeAssemblies||[]).some(a=>a.overlay&&x>=a.x&&y>=a.y&&x<a.x+a.w&&y<a.y+a.h&&a.overlay.mask[(y-a.y)*a.w+x-a.x]);out.push({id:key,mapId:map.id,map:map.name,x,y,state,canPromote:!!hasArtwork,code:'layer-intent',message:hasArtwork?'Walk behind conflicts with saved below-player artwork.':'This tile has no separate foreground layer. Use Separate foreground pixels to select the artwork and the floor beneath it.'});}return out;}
/** Return a copy; both original settings are retained in an audit trail. */
export function resolveProjectLayers(existing,decisions){const p=clone(existing);p.layerDecisions??={};p.layerDecisionHistory??=[];const conflicts=auditProjectLayers(p);for(const c of conflicts){const decision=decisions[c.id],choice=typeof decision==='object'?decision?.choice:decision;if(choice===undefined)continue;if(!['visual','walk-behind','split-ground'].includes(choice))throw Error('Choose saved visual masks or Walk behind.');const m=p.maps.find(m=>m.id===c.mapId),i=c.y*m.width+c.x,before=clone(visualState(m,c.x,c.y));if(choice==='split-ground')installGroundSplit(p,m,i,decision.split);if(choice==='walk-behind'||choice==='split-ground'){
 if(choice==='walk-behind'&&!c.canPromote)throw Error(c.map+' '+c.x+','+c.y+': add separate object/detail artwork before choosing Walk behind.');
 for(const k of ['details','objects','overhead'])if(m.layers[k]?.[i])m.layers[k][i]={...m.layers[k][i],renderRole:'foreground'};
 for(const o of m.objects||[])if(c.x>=o.x&&c.y>=o.y&&c.x<o.x+o.w&&c.y<o.y+o.h){o.renderMask??=Array.from({length:Math.ceil(o.h)},()=>Array(Math.ceil(o.w)).fill(o.renderRole||'behind'));o.renderMask[Math.floor(c.y-o.y)][Math.floor(c.x-o.x)]='foreground';}
 for(const a of m.nativeAssemblies||[])if(a.overlay&&c.x>=a.x&&c.y>=a.y&&c.x<a.x+a.w&&c.y<a.y+a.h){const j=(c.y-a.y)*a.w+c.x-a.x;if(a.overlay.mask[j]){a.renderIntents??=Array(a.w*a.h).fill(null);a.renderIntents[j]={version:1,layerType:(m.rom?.metatileLayers||2)===3?1:2};}}
 // Explicit ground stays on the bottom plane. Only the detail/object masks move.
 m.layerPriorityDecisions??={};m.layerPriorityDecisions[i]=2;
 }
 p.layerDecisions[c.id]={choice,state:JSON.stringify(visualState(m,c.x,c.y))};p.layerDecisionHistory.push({mapId:m.id,x:c.x,y:c.y,choice,...(choice==='split-ground'?{split:clone(decision.split)}:{}),before,after:clone(visualState(m,c.x,c.y))});}
 delete p.nativeArtworkPacks;return p;}
export function assertProjectLayers(project){const conflicts=auditProjectLayers(project);if(conflicts.length)throw Error(conflicts.length+' unresolved JSON layer conflicts. Open Export → Review JSON layer conflicts; your project has not been changed.');}

export function portalElevation(project,link,end){const point=link[end];if(Number.isInteger(point.elevation))return point.elevation;const baseline=link.rom?.[end==='from'?'originalFrom':'originalTo']||point,map=project.maps.find(m=>m.id===baseline.mapId),key=map?.rom?.key;for(const tag of link.rom?.events||[]){const t=/^(.+):warp-(\d+)$/.exec(tag);if(t?.[1]===key){const e=map.rom.events?.warps?.find(e=>e.index===+t[2]);if(e&&e.x===baseline.x&&e.y===baseline.y)return e.elevation??0;}}return 0;}
export function assertProjectPortals(project){const seen=new Map();for(const l of project.links||[]){if(l.runtime?.type!=='portal'&&!l.rom?.events?.some(t=>/:warp-\d+$/.test(t)))continue;for(const[end,other]of [['from','to'],...(l.twoWay?[['to','from']]:[])]){const a=l[end],b=l[other],key=a.mapId+':'+a.x+','+a.y+','+portalElevation(project,l,end),target=b.mapId+':'+b.x+','+b.y,old=seen.get(key);if(old&&old.target!==target)throw Error('Conflicting JSON exits at '+a.x+','+a.y+' in map '+a.mapId+': links '+old.id+' and '+l.id+' have different destinations. Resolve these in Connections; no ROM was written.');seen.set(key,{id:l.id,target});}}}
// Crop/resize changes coordinates, not the user's visual interpretation.
export function rebaseLayerDecisions(project,map,dx,dy){if(!project.layerDecisions)return;const moved=[];for(const[key,d]of Object.entries(project.layerDecisions)){const prefix=map.id+':';if(!key.startsWith(prefix))continue;const[x,y]=key.slice(prefix.length).split(',').map(Number),nx=x-dx,ny=y-dy;delete project.layerDecisions[key];if(nx>=0&&ny>=0&&nx<map.width&&ny<map.height)moved.push([id(map.id,nx,ny),{...d,state:JSON.stringify(visualState(map,nx,ny))}]);}for(const[k,d]of moved)project.layerDecisions[k]=d;}
